{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db_wooqer AS ( WITH preprocessed_data AS ( SELECT a.*, TO_DATE(a.\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\') AS process_date, EXTRACT(WEEK FROM TO_DATE(a.\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) AS week_number, CASE WHEN a.store = \'NEW BEL ROAD BANGALORE\' THEN \'SNITCH - COCO - BEL ROAD\' WHEN a.store = \'BHARTIYA CITY\' THEN \'SNITCH - COCO - BHARTIYA CITY\' WHEN a.store = \'ESPLANADE MALL\' THEN \'SNITCH - COCO - ESPLANADE MALL\' WHEN a.store = \'HILITE\' THEN \'SNITCH - COCO - HILITE\' WHEN a.store = \'HSR LAYOUT BANGALORE\' THEN \'SNITCH - COCO - HSR LAYOUT\' WHEN a.store = \'JAYANAGAR BANGALORE\' THEN \'SNITCH - COCO - JAYANAGAR\' WHEN a.store = \'MantriAvenue\' THEN \'SNITCH - COCO - KORMANGLA\' WHEN a.store = \'Lulu Mall\' THEN \'SNITCH - COCO - LULU MALL\' WHEN a.store = \'AMANORA\' THEN \'SNITCH - COFO - AMANORA\' WHEN a.store = \'BANER PUNE\' THEN \'SNITCH - COFO - BANER\' WHEN a.store = \'BRIGADE ROAD BANGALORE\' THEN \'SNITCH - COFO - BRIGADE ROAD\' WHEN a.store = \'CITY CENTER\' THEN \'SNITCH - COFO - CC MANGALORE\' WHEN a.store = \'INFINITI ANDHERI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.store = \'INFINITI MALAD\' THEN \'SNITCH - COFO - INFINITI MALAD\' WHEN a.store = \'INFINITY VASHI\' THEN \'SNITCH - COFO - INORBIT VASHI\' WHEN a.store = \'KUKATPALLY\' THEN \'SNITCH - COFO - KUKATPALLY\' WHEN a.store = \'BANDRA\' THEN \'SNITCH - COFO - LINKING ROAD\' WHEN a.store = \'Kalyan Metro\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.store = \'RAJPUR ROAD DEHRADUN\' THEN \'SNITCH - COFO - RAJPURA ROAD\' WHEN a.store = \'SARATH CITY\' THEN \'SNITCH - COFO - SARATH CITY\' WHEN a.store = \'TRIBECA\' THEN \'SNITCH - COFO - TRIBECA\' WHEN a.store = \'VIP ROAD VIZAG\' THEN \'SNITCH - COFO - VIZAG\' WHEN a.store = \'C ROAD JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.store = \'DB MALL BHOPAL\' THEN \'SNITCH - FOCO - DB MALL\' WHEN a.store = \'PMC CITADEL\' THEN \'SNITCH - FOCO - PHEONIX CITADEL\' WHEN a.store = \'SHYAMAL\' THEN \'SNITCH - FOCO - SHYAMAL\' WHEN a.store = \'TRION VADODARA\' THEN \'SNITCH - FOCO - TRION\' WHEN a.store = \'VAISHALI NAGAR JAIPUR\' THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN a.store = \'VR MALL SURAT\' THEN \'SNITCH - FOCO - VR MALL\' WHEN a.store = \'YAGNIK\' THEN \'SNITCH - FOCO - YAGNIK\' WHEN a.store = \'Hubli\' THEN \'Mapping Pending\' WHEN a.store = \'Kothapet\' THEN \'Mapping Pending\' WHEN a.store = \'Lajpat Nagar\' THEN \'Mapping Pending\' WHEN a.store = \'Phoenix Palassio\' THEN \'Mapping Pending\' WHEN a.store = \'Rajahmundry\' THEN \'Mapping Pending\' ELSE \'Unknown Store\' END AS store_name_mapping, a._AB_ADDITIONAL_PROPERTIES:\"Store Feedback\"::STRING AS store_feedback FROM snitch_db1_wooqer a ), store_count AS ( SELECT process_date, COUNT(DISTINCT store) AS total_stores FROM preprocessed_data GROUP BY process_date ), latest_date AS ( SELECT MAX(process_date) AS max_date FROM snitch_db_wooqer ), process_classification AS ( SELECT subquery.process, CASE WHEN MAX(subquery.count_per_store_week) > 1 THEN \'Daily\' ELSE \'Weekly\' END AS process_type FROM ( SELECT pd.process, pd.store, pd.week_number, COUNT(*) AS count_per_store_week FROM preprocessed_data pd GROUP BY pd.process, pd.store, pd.week_number ) subquery GROUP BY subquery.process ), active_processes AS ( SELECT DISTINCT process FROM snitch_db_wooqer, latest_date WHERE ( (process IN (SELECT process FROM process_classification WHERE process_type = \'Daily\') AND process_date BETWEEN max_date - INTERVAL \'3 DAYS\' AND max_date) OR (process IN (SELECT process FROM process_classification WHERE process_type = \'Weekly\') AND process_date BETWEEN max_date - INTERVAL \'7 DAYS\' AND max_date) ) ), process_count AS ( SELECT pd.store, pd.process_date, COUNT(DISTINCT CASE WHEN pc.process_type = \'Daily\' THEN pd.process END) AS daily_processes_completed, COUNT(DISTINCT CASE WHEN pc.process_type = \'Weekly\' THEN pd.process END) AS weekly_processes_completed FROM preprocessed_data pd JOIN process_classification pc ON pd.process = pc.process JOIN active_processes ap ON pd.process = ap.process GROUP BY pd.store, pd.process_date ), total_processes AS ( SELECT p.process_date, COUNT(DISTINCT CASE WHEN pc.process_type = \'Daily\' AND p.process_date BETWEEN p.process_date - INTERVAL \'3 DAYS\' AND p.process_date THEN p.process END) AS total_distinct_daily_processes, (SELECT COUNT(DISTINCT process) FROM process_classification WHERE process_type = \'Weekly\') AS total_distinct_weekly_processes FROM preprocessed_data p JOIN process_classification pc ON p.process = pc.process JOIN active_processes ap ON p.process = ap.process GROUP BY p.process_date ) SELECT pd.*, CASE WHEN ap.process IS NOT NULL THEN 1 ELSE 0 END AS ACTIVE_PROCESS_FLAG, c.AM, c.RM, c.CITY, c.state, c.REGION, c.partner, c.\"BRANCH CODE\", am_count.AM_store_count, rm_count.RM_store_count, sc.total_stores, pc.daily_processes_completed, pc.weekly_processes_completed, tp.total_distinct_daily_processes, tp.total_distinct_weekly_processes, pd.store_feedback FROM preprocessed_data pd LEFT JOIN store_count sc ON pd.process_date = sc.process_date LEFT JOIN process_count pc ON pd.store = pc.store AND pd.process_date = pc.process_date LEFT JOIN total_processes tp ON pd.process_date = tp.process_date LEFT JOIN active_processes ap ON pd.process = ap.process LEFT JOIN snitch_db.maplemonk.master_offine c ON TRIM(LOWER(pd.store_name_mapping)) = TRIM(LOWER(c.\"FROM BRANCH NAME\")) LEFT JOIN ( SELECT AM, COUNT(DISTINCT \"FROM BRANCH NAME\") AS AM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY AM ) am_count ON c.AM = am_count.AM LEFT JOIN ( SELECT \"RM\", COUNT(DISTINCT \"FROM BRANCH NAME\") AS RM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY \"RM\" ) rm_count ON c.RM = rm_count.RM ); CREATE OR REPLACE TABLE snitch_db_wooqer3 AS ( WITH store_list AS ( SELECT DISTINCT Store FROM snitch_db1_wooqer ), process_list AS ( SELECT DISTINCT Process FROM snitch_db1_wooqer WHERE Process NOT IN (\'GLOBAL COUNT WEDNESDAY\', \'VM Thursday\') AND TO_DATE(\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\') >= CURRENT_DATE - 2 ), date_list AS ( SELECT DISTINCT \"Date (dd/mm/yyyy)\" FROM snitch_db1_wooqer ), all_combinations AS ( SELECT d.\"Date (dd/mm/yyyy)\", s.Store, p.Process FROM date_list d CROSS JOIN store_list s CROSS JOIN process_list p ), full_entries AS ( SELECT ac.\"Date (dd/mm/yyyy)\", ac.Store, ac.Process, CASE WHEN wd.Store IS NOT NULL THEN \'Completed\' ELSE \'Missed\' END AS Status FROM all_combinations ac LEFT JOIN snitch_db1_wooqer wd ON ac.\"Date (dd/mm/yyyy)\" = wd.\"Date (dd/mm/yyyy)\" AND ac.Store = wd.Store AND ac.Process = wd.Process ) SELECT \"Date (dd/mm/yyyy)\", Store, LISTAGG(CASE WHEN Status = \'Completed\' THEN Process END, \', \') WITHIN GROUP (ORDER BY Process) AS \"Completed Process\", LISTAGG(CASE WHEN Status = \'Missed\' THEN Process END, \', \') WITHIN GROUP (ORDER BY Process) AS \"Missed Process\" FROM full_entries GROUP BY \"Date (dd/mm/yyyy)\", Store )",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            